<script setup lang="ts">
import {ElButton,ElPopover} from 'element-plus'
import 'element-plus/es/components/popover/style/css'
import {isDesktopClient} from '../services/serverConfig'
import {inferMediaType} from '../services/filePreview'
import {computed,defineAsyncComponent,nextTick,onBeforeUnmount,onMounted,ref,shallowRef,watch} from 'vue'
import {cachedAttachment,pinAttachmentCache,openAttachmentContent,type AttachmentItem,type AttachmentReference} from '../services/attachments'
import AttachmentDiagnosticDialog from './AttachmentDiagnosticDialog.vue'
import {diagnosticOpen,recordAttachmentAttempt,attachmentErrorCode} from '../services/attachmentDiagnostics'
import MarkdownPreview from './MarkdownPreview.vue'
import AttachmentCacheStatus from './AttachmentCacheStatus.vue'
const transfer=ref({loaded:0,total:0}),cacheState=ref<{source:string;persistent:boolean;pinned:boolean}|null>(null);let downloadController:AbortController|undefined
const PdfDocumentPreview=defineAsyncComponent(()=>import('./PdfDocumentPreview.vue'))
const externalActionLabel=isDesktopClient()?'用系统程序打开':'下载后打开'
const pdfBlob=shallowRef<Blob>(),diagnosticOpenState=ref(false)
type PreviewAttachment=AttachmentItem&{references?:AttachmentReference[]}
const props=defineProps<{ownerId:string;items:PreviewAttachment[];index:number}>(),emit=defineEmits<{close:[];change:[index:number]}>()
const current=computed(()=>props.items[props.index]),url=ref(''),text=ref(''),loading=ref(false),error=ref(''),zoom=ref(1),rotation=ref(0);let generation=0
const raster=computed(()=>/^image\/(jpeg|png|webp|gif|bmp|avif)$/i.test(inferMediaType(current.value?.originalFilename||'',current.value?.mediaType||'')))
const pdf=computed(()=>current.value?.mediaType==='application/pdf'||/\.pdf$/i.test(current.value?.originalFilename||''))
const audio=computed(()=>current.value?.mediaType?.startsWith('audio/'))
const video=computed(()=>current.value?.mediaType?.startsWith('video/'))
const markdown=computed(()=>/\.(md|markdown)$/i.test(current.value?.originalFilename||'')||current.value?.mediaType==='text/markdown')
const textLike=computed(()=>markdown.value||/^(text\/|application\/(json|xml|yaml|x-yaml))/.test(current.value?.mediaType||'')||/\.(txt|json|ya?ml|xml|csv|log|ini|conf|js|ts|jsx|tsx|vue|css|scss|html|java|kt|py|rs|go|sql|sh|ps1)$/i.test(current.value?.originalFilename||''))
const supported=computed(()=>raster.value||pdf.value||audio.value||video.value||textLike.value)
const extension=computed(()=>{const match=current.value?.originalFilename.match(/\.([^.]+)$/);return(match?.[1]||current.value?.mediaType?.split('/')[1]||'FILE').slice(0,10).toUpperCase()})
function bytes(value=0){if(value<1024)return`${value} B`;if(value<1024**2)return`${(value/1024).toFixed(1)} KB`;return`${(value/1024**2).toFixed(value<1024**3?1:0)} MB`}
function release(){downloadController?.abort();if(url.value)URL.revokeObjectURL(url.value);url.value='';text.value='';pdfBlob.value=undefined}
async function load(){const item=current.value;if(!item)return;const request=++generation;release();error.value='';zoom.value=1;rotation.value=0;if(!supported.value)return;if(textLike.value&&item.sizeBytes>5*1024*1024){error.value='文本文件超过 5 MB，请使用系统程序打开';return}loading.value=true;transfer.value={loaded:0,total:0};cacheState.value=null;downloadController=new AbortController();try{const blob=await cachedAttachment(props.ownerId,item,{signal:downloadController.signal,onDownloadProgress:event=>{if(request===generation)transfer.value={loaded:event.loaded,total:event.total||0}},onState:value=>{if(request===generation)cacheState.value=value}});if(request!==generation)return;if(pdf.value)pdfBlob.value=blob;else if(textLike.value){let value=await blob.text();if(/\.json$/i.test(item.originalFilename)||item.mediaType==='application/json')try{value=JSON.stringify(JSON.parse(value),null,2)}catch{}text.value=value}else url.value=URL.createObjectURL(blob.slice(0,blob.size,inferMediaType(item.originalFilename,item.mediaType)))}catch(source){if(request===generation){error.value=downloadController?.signal.aborted?'下载已取消，可点击重试':source instanceof Error?source.message:'附件预览失败';recordAttachmentAttempt(props.ownerId,item,'preview',attachmentErrorCode(source))}}finally{if(request===generation)loading.value=false}}
// PDF保留引擎的具体失败原因；图片和媒体的原生事件继续使用通用提示。
function previewFailed(source?:unknown){error.value=typeof source==='string'?source:'附件渲染失败，请检查格式或使用系统程序打开';if(current.value)recordAttachmentAttempt(props.ownerId,current.value,'preview','RENDER_FAILED')}
function move(offset:number){const next=props.index+offset;if(next>=0&&next<props.items.length)emit('change',next)}
function keydown(event:KeyboardEvent){if(diagnosticOpenState.value)return;if(event.key==='Escape')emit('close');else if(event.key==='ArrowLeft')move(-1);else if(event.key==='ArrowRight')move(1);else if((event.key==='+'||event.key==='=')&&raster.value)zoom.value=Math.min(4,zoom.value+.2);else if(event.key==='-'&&raster.value)zoom.value=Math.max(.2,zoom.value-.2)}
async function systemOpen(){if(!current.value)return;try{await diagnosticOpen(props.ownerId,current.value)}catch(source){error.value=source instanceof Error?source.message:'系统程序打开失败'}}
watch(()=>[props.ownerId,props.index,current.value?.uid,current.value?.contentUrl,current.value?.sha256],()=>void load(),{immediate:true});onMounted(()=>{window.addEventListener('keydown',keydown);void nextTick(()=>document.querySelector<HTMLElement>('.attachment-preview-dialog')?.focus())});onBeforeUnmount(()=>{generation++;release();window.removeEventListener('keydown',keydown)})
async function toggleOffline(){const item=current.value;if(!item||!cacheState.value)return;try{cacheState.value.pinned=await pinAttachmentCache(props.ownerId,item,!cacheState.value.pinned)}catch(source){error.value=source instanceof Error?source.message:'离线保留失败'}}
</script>
<template><Teleport to="body"><div class="attachment-preview-mask" role="dialog" aria-modal="true" :aria-label="`预览 ${current?.originalFilename||'附件'}`" @click.self="emit('close')"><section v-if="current" class="attachment-preview-dialog" :class="{'pdf-preview':pdf}" tabindex="-1"><header><button class="back" @click="emit('close')">← 返回附件</button><div><strong :title="current.originalFilename">{{current.originalFilename}}</strong><small>{{index+1}} / {{items.length}}<template v-if="pdf"> · {{current.mediaType||'PDF'}} · {{bytes(current.sizeBytes)}}</template></small></div><nav><ElPopover v-if="pdf&&current.references" trigger="click" placement="bottom-end" :width="280"><template #reference><ElButton text aria-label="附件引用信息">引用信息</ElButton></template><p v-if="current.references.length">引用于 {{current.references.map(value=>value.noteTitle||value.title).filter(Boolean).join('、')}}</p><p v-else>无引用附件</p></ElPopover><AttachmentCacheStatus v-if="!loading&&cacheState" :state="cacheState" @toggle="toggleOffline"/><template v-if="raster"><button title="缩小" @click="zoom=Math.max(.2,zoom-.2)">−</button><span>{{Math.round(zoom*100)}}%</span><button title="放大" @click="zoom=Math.min(4,zoom+.2)">＋</button><button title="向右旋转" @click="rotation=(rotation+90)%360">↻</button></template><button @click="diagnosticOpenState=true">检查附件</button><button @click="systemOpen">{{externalActionLabel}}</button><button class="close" aria-label="关闭" @click="emit('close')">×</button></nav></header><main><button class="previous" :disabled="index===0" aria-label="上一个附件" @click="move(-1)">‹</button><div class="stage" :class="{document:pdf||textLike,pdf,media:audio||video,'transfer-state':loading||Boolean(error)}"><p v-if="loading">正在下载文件 {{Math.ceil(transfer.loaded/1024)}} KB <button @click="downloadController?.abort()">取消</button></p><p v-else-if="error" class="error">{{error}} <button @click="load">重试下载</button> <button @click="diagnosticOpenState=true">检查附件</button></p><img v-else-if="raster&&url" :src="url" @error="previewFailed" :alt="current.originalFilename" :style="{transform:`scale(${zoom}) rotate(${rotation}deg)`}" @dblclick="zoom=zoom===1?2:1"><PdfDocumentPreview v-else-if="pdf&&pdfBlob" :blob="pdfBlob" :owner-id="ownerId" :filename="current.originalFilename" @error="previewFailed"/><MarkdownPreview v-else-if="markdown" class="markdown-document" :content="text"/><pre v-else-if="textLike">{{text}}</pre><audio v-else-if="audio&&url" :src="url" @error="previewFailed" controls/><video v-else-if="video&&url" :src="url" @error="previewFailed" controls/><div v-else class="unsupported"><b>{{extension}}</b><strong>此格式暂不支持应用内预览</strong><span>{{isDesktopClient()?'文件已经安全保留，可以使用系统程序打开。':'下载到本机后，可使用系统程序打开。'}}</span><button @click="systemOpen">{{externalActionLabel}}</button></div></div><button class="next" :disabled="index===items.length-1" aria-label="下一个附件" @click="move(1)">›</button></main><footer v-if="!pdf"><span>{{current.mediaType||'未知格式'}} · {{bytes(current.sizeBytes)}}</span><span v-if="current.references?.length">引用于 {{current.references.map(value=>value.noteTitle||value.title).filter(Boolean).join('、')}}</span><span v-else-if="current.references" class="orphan">无引用附件</span><span v-else>当前内容的附件</span></footer></section></div></Teleport><AttachmentDiagnosticDialog v-if="diagnosticOpenState&&current" :owner-id="ownerId" :item="current" @close="diagnosticOpenState=false"/></template>
<style scoped>
.attachment-preview-mask{position:fixed;z-index:1200;inset:0;display:grid;place-items:center;padding:22px;background:rgba(10,18,13,.72);backdrop-filter:blur(7px)}.attachment-preview-dialog{display:grid;grid-template-rows:auto minmax(0,1fr) auto;width:min(1180px,calc(100vw - 44px));height:min(820px,calc(100vh - 44px));overflow:hidden;border:1px solid #d7e0da;border-radius:15px;outline:0;background:#f7f9f7;box-shadow:0 30px 100px #07110b80}.attachment-preview-dialog>header{display:grid;grid-template-columns:150px minmax(0,1fr) auto;align-items:center;gap:14px;padding:11px 14px;border-bottom:1px solid #dce4df;background:#fff}.attachment-preview-dialog button{border:1px solid #d4ded8;border-radius:7px;background:#fff;color:#405149;font-size:9px;cursor:pointer}.back{padding:8px 10px}.attachment-preview-dialog header>div{display:grid;min-width:0;text-align:center}.attachment-preview-dialog header strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px}.attachment-preview-dialog header small{color:#839087;font-size:8px}.attachment-preview-dialog nav{display:flex;align-items:center;gap:5px}.attachment-preview-dialog nav button{height:30px;padding:0 9px}.attachment-preview-dialog nav span{min-width:42px;color:#6f7c74;font-size:8px;text-align:center}.attachment-preview-dialog nav .close{width:30px;padding:0;font-size:18px}.attachment-preview-dialog>main{position:relative;display:grid;grid-template-columns:48px minmax(0,1fr) 48px;min-height:0;background:#e9eeeb}.stage{display:grid;place-items:center;min-width:0;min-height:0;overflow:auto;background-image:linear-gradient(45deg,#e2e7e4 25%,transparent 25%),linear-gradient(-45deg,#e2e7e4 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#e2e7e4 75%),linear-gradient(-45deg,transparent 75%,#e2e7e4 75%);background-position:0 0,0 8px,8px -8px,-8px 0;background-size:16px 16px}.stage img{display:block;max-width:calc(100% - 40px);max-height:calc(100% - 40px);object-fit:contain;transition:transform .14s ease;transform-origin:center}.stage>p{padding:12px 16px;border-radius:8px;background:#ffffffde;color:#69766e;font-size:10px}.stage>p.error{color:#a14444}.stage.document{display:block;padding:18px;background:#dfe5e1}.stage iframe{width:100%;height:100%;border:0;border-radius:8px;background:#fff}.stage pre{box-sizing:border-box;width:100%;min-height:100%;margin:0;padding:24px;overflow:auto;border-radius:8px;background:#fff;color:#27342d;font:10px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap;word-break:break-word}.stage .markdown-document{box-sizing:border-box;width:min(860px,100%);min-height:100%;margin:auto;padding:30px 42px;border-radius:8px;background:#fff}.stage.media{background:#172019}.stage audio{width:min(680px,calc(100% - 50px))}.stage video{max-width:calc(100% - 50px);max-height:calc(100% - 50px)}.previous,.next{z-index:2;margin:auto;width:34px;height:52px;border:0!important;border-radius:10px!important;background:#fff9!important;font-size:27px!important}.previous:disabled,.next:disabled{opacity:.25}.unsupported{display:grid;place-items:center;gap:10px;max-width:380px;padding:38px;border:1px solid #d9e1dc;border-radius:14px;background:#fffffff2;text-align:center}.unsupported>b{padding:12px 16px;border-radius:9px;background:#eaf2ed;color:#42604f;font-size:18px}.unsupported strong{font-size:13px}.unsupported span{color:#7c8981;font-size:9px}.unsupported button{margin-top:8px;padding:9px 13px}.attachment-preview-dialog>footer{display:flex;justify-content:space-between;gap:20px;padding:10px 16px;border-top:1px solid #dce4df;background:#fff;color:#738078;font-size:8px}.attachment-preview-dialog>footer span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.attachment-preview-dialog>footer .orphan{color:#a36b2b}
</style>

<style scoped>.attachment-preview-dialog{grid-template-rows:auto minmax(0,1fr) auto}.attachment-preview-dialog.pdf-preview{grid-template-rows:auto minmax(0,1fr)}.stage.pdf{display:flex;padding:0;overflow:hidden}.stage.pdf>.pdf-document-preview{flex:1}</style>

<style scoped>
/* 文档/PDF正文使用不同布局，传输与错误提示独立居中，不能继承正文的左上排列。 */
.stage.transfer-state{display:grid;place-items:center;padding:16px;box-sizing:border-box}
.stage.transfer-state>p{max-width:100%;margin:0;box-sizing:border-box;text-align:center;overflow-wrap:anywhere}
</style>
